using NUnit.Framework;
using SaferAccessors.Tests;

namespace SaferAccessors.Analysis.Tests.Generators;

internal static class FieldAccessorGeneratorTests
{
	[Test]
	public static async Task GenerateWithInstanceEditableFieldAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private int id;
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension(global::Test self)
				{
					public int id
					{
						get => TestAccessors.id(self);
						set => TestAccessors.id(self) = value;
					}
				}
				
				private static partial class TestAccessors
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Field, Name = "id")]
					public static extern ref int id(global::Test self);
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}

